package com.acme.pricing

import kotlinx.coroutines.async
import kotlinx.coroutines.launch
import kotlinx.coroutines.test.runTest
import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Test

class PriceLoaderJoinTest {
    @Test
    fun `loads two prices concurrently`() = runTest {
        val loader = PriceLoader(FakePriceApi(mapOf("A1" to 999, "B2" to 450)), PriceCache())
        val a = async { loader.load("A1") }
        val job = launch { loader.load("B2") }

        assertEquals(999, a.await())
        job.join()
        assertEquals(450, loader.cached("B2"))
    }
}

